import{_ as a,o as t,c as r,ak as n}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse('{"title":"Branches","description":"","frontmatter":{"title":"Branches","lang":"en-US"},"headers":[],"relativePath":"features/branches.md","filePath":"features/branches.md","lastUpdated":1788708420000}'),o={name:"features/branches.md"};function s(i,e,h,l,c,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="branches" tabindex="-1">Branches <a class="header-anchor" href="#branches" aria-label="Permalink to &quot;Branches&quot;">​</a></h1><p>Every run Piwi stores is tagged with the git <strong>branch</strong> it came from, and that branch is a real, queryable dimension — not a string buried in metadata. Filter any view to one branch, compare like with like, and let baselines and flakiness scoring stop mixing your feature branches together. This is the headline of 0.26: branch-aware runs and baselines.</p><p><strong>Needs:</strong> the reporter only — the branch is collected automatically with the rest of the git metadata (<code>collectScmInfo</code>, on by default). Nothing to install or switch on.</p><h2 id="how-the-branch-is-recorded" tabindex="-1">How the branch is recorded <a class="header-anchor" href="#how-the-branch-is-recorded" aria-label="Permalink to &quot;How the branch is recorded&quot;">​</a></h2><p>On CI, git alone is unreliable: a pull-request checkout is usually a detached <code>HEAD</code>, so <code>git rev-parse</code> reports the literal string <code>HEAD</code> instead of a branch. The reporter resolves the real branch through a fallback chain instead:</p><ol><li><strong><code>PIWI_BRANCH</code></strong> — an explicit operator override, when you want to name the branch yourself.</li><li><strong>The CI provider&#39;s branch variables</strong> — <code>GITHUB_HEAD_REF</code> / <code>GITHUB_REF_NAME</code> on GitHub Actions, the merge-request and commit refs on GitLab, and the equivalents for CircleCI, Travis, Azure, Jenkins and Bitbucket. On a pull-request build the <strong>source</strong> branch wins over the plain ref, so the run records the branch under test.</li><li><strong><code>git rev-parse --abbrev-ref HEAD</code></strong> — the local answer, used only when it is a real branch. A detached <code>HEAD</code> is discarded rather than recorded.</li></ol><p>When the provider exposes it, the reporter also captures the <strong>pull-request number</strong>, so <a href="/guide/ci.html#pull-request-feedback">pull-request feedback</a> can look the PR up exactly instead of guessing from the branch name. Branch and PR detection happen automatically as part of CI collection — see <a href="/guide/ci.html#what-gets-detected">CI &amp; sharding → What gets detected</a>.</p><h2 id="the-default-branch" tabindex="-1">The default branch <a class="header-anchor" href="#the-default-branch" aria-label="Permalink to &quot;The default branch&quot;">​</a></h2><p>Each project has a <strong>Default branch</strong> setting on its <strong>Settings</strong> tab (placeholder <code>e.g. main</code>). Leave it blank and Piwi resolves it from your SCM provider. The default branch is the reference point for the rest of this page: baselines fall back to it, and &quot;already flaky on the default branch&quot; is measured against it.</p><h2 id="filtering-by-branch" tabindex="-1">Filtering by branch <a class="header-anchor" href="#filtering-by-branch" aria-label="Permalink to &quot;Filtering by branch&quot;">​</a></h2><p>On a project page, the filter bar carries a <strong>branch</strong> multi-select (the git-branch icon, &quot;All branches&quot;) next to the environment filter. It appears once the project has runs from more than one branch, and it scopes the <strong>runs list</strong> and the <strong>flaky leaderboard</strong> to the branches you pick. <a href="./analytics.html">Analytics</a> has its own branch scope control, so a pass-rate trend or slow-test table can be read for one branch at a time.</p><p>Because the branch is an indexed column, these filters are served by the database rather than by fetching a wide batch and sifting metadata in memory. Runs reported before the column existed fall back to the branch recorded in their metadata, so old history still filters.</p><h2 id="branch-aware-baselines" tabindex="-1">Branch-aware baselines <a class="header-anchor" href="#branch-aware-baselines" aria-label="Permalink to &quot;Branch-aware baselines&quot;">​</a></h2><p>The bigger change is invisible until you look for it: <strong>baselines are chosen within a branch.</strong></p><ul><li><strong>Regression signals</strong> — the <em>new regression</em> and <em>new flaky</em> badges on an execution compare against the most recent passing run on the <strong>same branch</strong>, then fall back to the default branch. Two feature branches reporting interleaved runs no longer become each other&#39;s baseline.</li><li><strong>The visual-diff baseline</strong> (<a href="./run-changes.html">What changed in a run</a>) prefers the same branch the same way, so a screenshot diff compares against a run that shares your branch&#39;s state.</li><li><strong>Pull-request feedback</strong> builds its &quot;new failures vs. pre-existing&quot; split from those same branch-aware signals, and <strong>exonerates</strong> a test that is already flaky on the default branch — a failure the PR did not introduce is reported as pre-existing rather than blamed on the change. The <code>max-new-regressions</code> <a href="/guide/ci.html#blocking-a-merge">CI gate</a> then counts the right number.</li></ul><h2 id="from-an-agent-mcp" tabindex="-1">From an agent (MCP) <a class="header-anchor" href="#from-an-agent-mcp" aria-label="Permalink to &quot;From an agent (MCP)&quot;">​</a></h2><p>The MCP tools take a branch filter too: <code>list_runs</code> and the flaky tools accept a <code>branch</code> argument, so an agent can ask &quot;what is failing on <code>main</code>&quot; or &quot;is this test flaky on my branch&quot; without pulling every run. See the <a href="/features/mcp.html">MCP server</a>.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Notification subscriptions can filter by branch and alert only on the default branch, so a noisy work-in-progress branch does not page you. See <a href="./notifications.html">Notifications &amp; alerts</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Branch scoping is opt-in per view, not yet the default.</strong> Flakiness scores and trends aggregate across every branch until you apply the filter; scoping them to the default branch <em>by default</em> is on the roadmap.</li><li><strong>Branches are a run dimension, not yet entities.</strong> There is no per-branch merge-readiness verdict, branch-class gate policy, or retention by branch class yet — those are the &quot;branches as entities&quot; work still under <em>Exploring</em> in the <a href="https://github.com/PiwiTests/platform/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">roadmap</a>.</li><li><strong>A run needs a resolvable branch.</strong> A purely local run with no CI variables, a detached <code>HEAD</code>, and no <code>PIWI_BRANCH</code> records no branch at all, so it will not appear under any branch filter.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ci.html">CI &amp; sharding</a> — how the branch and PR number are detected on each provider</li><li><a href="./flaky-tests.html">Flaky tests</a> — the leaderboard and regression signals the branch filter scopes</li><li><a href="./analytics.html">Analytics</a> — trends you can read one branch at a time</li><li><a href="/guide/concepts.html">Core concepts</a> — where branch sits among run, execution and baseline</li></ul>',23)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
